    for i in range(len(orders)):
        if orders[i] > 100:
            # Ensure we don't go out of bounds on the last element
            if i < len(orders) - 1:
                results.append(orders[i] > orders[i+1])
            else:
                results.append(False)
        else:
            results.append(False)
    return results
